102	    total_is_partial: bool,
103	    /// Projection GEMMs served by the pinned cuBLASLt algo this run: >0 under Pin (every GEMM
104	    /// serves or the run bails), 0 under Tuned/PerToken.
105	    pin_served: u64,
106	    /// Projection GEMMs served by the per-token oracle this run: >0 under PerToken, 0 otherwise.
107	    per_token_served: u64,
108	    schedule: Vec<KernelCall>,
109	    by_op: Vec<RollupRow>,
110	    by_call_site: Vec<CallSiteRow>,
111	    coverage: Vec<CoverageRow>,
