139	/// A measured op under this run's policy: `Faithful` carries the latency that feeds the rollup;
140	/// `Excluded` carries only the reason, so no latency exists to leak into the totals or coverage.
141	enum Measure {
142	    Faithful(LatencyStats),
143	    Excluded(ExcludeReason),
144	}
145	
146	#[derive(Clone, Copy)]
147	enum ExcludeReason {
148	    /// Tuned projection GEMM: the report's untuned context would run plain GemmEx (not the
149	    /// production gemm_lt-tuned algo) if measured, so it is classified excluded and skipped.
150	    UnfaithfulGemmEx,
151	}
152	
153	impl ExcludeReason {
154	    fn status(self) -> &'static str {
155	        match self {
156	            ExcludeReason::UnfaithfulGemmEx => "unfaithful_gemmex",
157	        }
158	    }
159	}
160	
161	fn classify(policy: NumericPolicy, op: &str) -> Option<ExcludeReason> {
162	    if matches!(op, "gemm" | "gemm_rows") && matches!(policy, NumericPolicy::Tuned) {
163	        Some(ExcludeReason::UnfaithfulGemmEx)
164	    } else {
165	        None
166	    }
167	}
168	
169	fn parse_policy(s: &str) -> Result<NumericPolicy> {
170	    match s {
171	        "tuned" => Ok(NumericPolicy::Tuned),
172	        "pin" => Ok(NumericPolicy::Pin),
173	        "per-token" => Ok(NumericPolicy::PerToken),
174	        other => bail!("--policy must be tuned | pin | per-token, got `{other}`"),
175	    }
176	}
177	
178	fn policy_name(p: NumericPolicy) -> &'static str {
179	    match p {
180	        NumericPolicy::Tuned => "tuned",
181	        NumericPolicy::Pin => "pin",
182	        NumericPolicy::PerToken => "per-token",
183	    }
184	}
185	
186	fn main() -> Result<()> {
187	    let cli = Cli::parse();
188	    if cli.command != PHASE_DECODE {
189	        bail!("only `decode` is implemented; got `{}`", cli.command);
190	    }
191	    if cli.batch_size == 0 {
192	        bail!("--batch-size must be greater than zero");
193	    }
194	    if cli.kv_len == 0 {
195	        bail!("--kv-len must be greater than zero");
196	    }
197	    if cli.iters == 0 {
198	        bail!("--iters must be greater than zero");
199	    }
200	    if cli.format != "text" && cli.format != "json" {
201	        bail!("--format must be `text` or `json`");
202	    }
203	
204	    let policy = parse_policy(&cli.policy)?;
205	    set_numeric_policy(policy);
206	
207	    let schedule = trace_decode_kernel_calls(&cli.model_path, cli.batch_size, cli.kv_len)?;
208	    reset_numeric_policy_counters();
209	    let catalog = measure_catalog(&schedule, cli.iters, policy)
210	        .with_context(|| "failed to build strict measured catalog")?;
211	    // launch_gemm_pin bails on an un-warmed shape, with no silent fallback.
212	    let pin_served_count = pin_served();
213	    if matches!(policy, NumericPolicy::Pin) {
214	        anyhow::ensure!(
215	            pin_served_count > 0,
216	            "no projection GEMM served through the Pin path (served=0); policy didn't take effect or the pins weren't warmed"
217	        );
218	    }
219	    // PerToken must route through the per-token oracle, not silently fall back to GemmEx
220	    // (which would still report `measured`).
221	    let per_token_served_count = per_token_served();
222	    if matches!(policy, NumericPolicy::PerToken) {
223	        anyhow::ensure!(
224	            per_token_served_count > 0,
225	            "no projection GEMM served through the PerToken oracle (served=0); policy didn't take effect"
226	        );
227	    }
228	    let report = compose_report(
229	        cli.batch_size,
230	        cli.kv_len,
231	        cli.iters,
232	        schedule,
233	        &catalog,
234	        policy,
235	        pin_served_count,
236	        per_token_served_count,
237	    )?;
238	    let out = cli.out.unwrap_or_else(|| {
239	        // Key the default path on the policy too: pin/tuned/per-token runs differ, so without it a
240	        // later run silently overwrites an earlier one's JSON/DOT.
241	        PathBuf::from(format!(
242	            "target/model_reports/{MODEL}/decode-{}-bs{}-kv{}.json",
243	            policy_name(policy),
244	            cli.batch_size,
245	            cli.kv_len
246	        ))
247	    });
248	    write_json_report(&out, &report)?;
249	    let dot_out = out.with_extension("dot");
250	    write_dot_report(&dot_out, &report)?;
251	
252	    match cli.format.as_str() {
253	        "text" => print_text_report(&report, &out, &dot_out),
254	        "json" => {
255	            println!("{}", serde_json::to_string_pretty(&report)?);
256	            eprintln!("wrote {}", out.display());
257	            eprintln!("wrote {}", dot_out.display());
258	        }
259	        _ => unreachable!("format validated above"),
260	    }
261	
262	    Ok(())
263	}
264	
265	fn write_json_report(path: &Path, report: &ModelReport) -> Result<()> {
266	    if let Some(parent) = path.parent() {
267	        fs::create_dir_all(parent)
268	            .with_context(|| format!("failed to create {}", parent.display()))?;
269	    }
270	    let json = serde_json::to_string_pretty(report)?;
271	    fs::write(path, json).with_context(|| format!("failed to write {}", path.display()))
272	}
273	
274	fn write_dot_report(path: &Path, report: &ModelReport) -> Result<()> {
275	    if let Some(parent) = path.parent() {
276	        fs::create_dir_all(parent)
277	            .with_context(|| format!("failed to create {}", parent.display()))?;
278	    }
279	    let mut site_order = Vec::new();
280	    for call in &report.schedule {
281	        let site = normalize_call_site(&call.label);
282	        if !site_order.contains(&site) {
283	            site_order.push(site);
284	        }
285	    }
286	    let rows = report
287	        .by_call_site
288	        .iter()
289	        .map(|row| (row.call_site.as_str(), row))
290	        .collect::<HashMap<_, _>>();
291	    // Drop sites with no rollup row (e.g. GEMM excluded under Tuned) so the edge chain skips them
292	    // instead of leaving Graphviz to auto-create phantom nodes for the dangling endpoints.
293	    site_order.retain(|site| rows.contains_key(site.as_str()));
294	    let mut dot = String::new();
295	    dot.push_str("digraph qwen3_decode_operator_report {\n");
296	    dot.push_str("  rankdir=LR;\n");
297	    dot.push_str("  graph [fontname=\"Helvetica\"];\n");
298	    dot.push_str("  node [shape=box, style=\"rounded,filled\", fontname=\"Helvetica\", fillcolor=\"#f8fafc\", color=\"#94a3b8\"];\n");
299	    dot.push_str("  edge [color=\"#94a3b8\"];\n");
300	    for site in &site_order {
301	        let Some(row) = rows.get(site.as_str()) else {
302	            continue;
303	        };
304	        let fill = if row.pct >= 25.0 {
305	            "#fee2e2"
306	        } else if row.pct >= 10.0 {
307	            "#ffedd5"
308	        } else if row.pct >= 2.0 {
309	            "#fef9c3"
310	        } else {
311	            "#f8fafc"
312	        };
313	        writeln!(
314	            dot,
315	            "  \"{}\" [fillcolor=\"{}\", label=\"{}\\n{}\\nmean {} · p99/call {} · {:.1}%\"];",
316	            dot_escape(site),
317	            fill,
318	            dot_escape(site),
319	            dot_escape(&row.op),
320	            format_us(row.total_us),
321	            format_us(row.p99_us),
322	            row.pct
323	        )?;
324	    }
325	    for window in site_order.windows(2) {
326	        writeln!(
327	            dot,
328	            "  \"{}\" -> \"{}\";",
329	            dot_escape(&window[0]),
330	            dot_escape(&window[1])
331	        )?;
332	    }
333	    dot.push_str("}\n");
334	    fs::write(path, dot).with_context(|| format!("failed to write {}", path.display()))
335	}
336	
337	fn compose_report(
338	    batch_size: usize,
339	    kv_len: usize,
340	    iters: u64,
341	    schedule: Vec<KernelCall>,
342	    catalog: &HashMap<String, BenchEntry>,
343	    policy: NumericPolicy,
344	    pin_served_count: u64,
345	    per_token_served_count: u64,
346	) -> Result<ModelReport> {
347	    let mut op_rows: BTreeMap<String, Accum> = BTreeMap::new();
348	    let mut site_rows: BTreeMap<String, (String, Accum)> = BTreeMap::new();
349	    let mut coverage_rows: BTreeMap<(String, String), CoverageRow> = BTreeMap::new();
350	    let mut missing = Vec::new();
351	
352	    for call in &schedule {
353	        let site = normalize_call_site(&call.label);
354	        if is_noop_all_reduce(call) {
355	            // Counted toward call totals but contributes zero time on a single rank.
356	            let zero = LatencyStats::zero(iters);
357	            accumulate(op_rows.entry(call.op.clone()).or_default(), &zero);
358	            let (_, site_accum) = site_rows
359	                .entry(site.clone())
360	                .or_insert_with(|| (call.op.clone(), Accum::default()));
361	            accumulate(site_accum, &zero);
362	            coverage_rows
363	                .entry((site.clone(), call.op.clone()))
364	                .and_modify(|row| row.calls += 1)
365	                .or_insert(CoverageRow {
366	                    call_site: site,
367	                    op: call.op.clone(),
368	                    status: "no_op".to_string(),
369	                    calls: 1,
370	                    latency: Some(zero),
371	                    key: None,
372	                });
373	            continue;
374	        }
375	
376	        let key = bench_key(call)?;
377	        let Some(entry) = catalog.get(&key) else {
378	            missing.push(format!(
379	                "op={} label={} key={key}\n{}",
380	                call.op,
381	                call.label,
382	                describe_call(call)
383	            ));
384	            continue;
385	        };
386	
387	        if let Measure::Faithful(stats) = &entry.measure {
388	            accumulate(op_rows.entry(call.op.clone()).or_default(), stats);
389	            let (_, site_accum) = site_rows
390	                .entry(site.clone())
391	                .or_insert_with(|| (call.op.clone(), Accum::default()));
392	            accumulate(site_accum, stats);
393	        }
394	        coverage_rows
395	            .entry((site.clone(), call.op.clone()))
396	            .and_modify(|row| row.calls += 1)
397	            .or_insert(CoverageRow {
398	                call_site: site,
399	                op: call.op.clone(),
400	                status: match &entry.measure {
401	                    Measure::Faithful(_) => "measured",
402	                    Measure::Excluded(reason) => reason.status(),
403	                }
404	                .to_string(),
405	                calls: 1,
406	                latency: match &entry.measure {
407	                    Measure::Faithful(stats) => Some(stats.clone()),
408	                    Measure::Excluded(_) => None,
409	                },
410	                key: Some(entry.key.clone()),
411	            });
412	    }
413	
414	    if !missing.is_empty() {
415	        bail!("missing bench result:\n{}", missing.join("\n\n"));
416	    }
417	
418	    // Re-derived from the per-op accumulators (no-op all-reduce contributes 0),
419	    // so totals are summed in op order rather than schedule order, a sub-ULP
420	    // reshuffle that only touches this untracked target/ report.
421	    let total = op_rows.values().map(|accum| accum.total_us).sum::<f64>();
422	    let total_p99 = op_rows
423	        .values()
424	        .map(|accum| accum.total_p99_us)
425	        .sum::<f64>();
426	
427	    let mut by_op: Vec<_> = op_rows
428	        .into_iter()
429	        .map(|(op, accum)| rollup_row(op, accum, total))
430	        .collect();
431	    by_op.sort_by(|a, b| b.total_us.total_cmp(&a.total_us).then(a.op.cmp(&b.op)));
432	
433	    let mut by_call_site: Vec<_> = site_rows
434	        .into_iter()
435	        .map(|(call_site, (op, accum))| call_site_row(call_site, op, accum, total))
436	        .collect();
437	    by_call_site.sort_by(|a, b| {
438	        b.total_us
439	            .total_cmp(&a.total_us)
440	            .then(a.call_site.cmp(&b.call_site))
441	    });
442	
443	    let total_is_partial = catalog
444	        .values()
445	        .any(|entry| matches!(entry.measure, Measure::Excluded(_)));
446	
447	    Ok(ModelReport {
448	        schema: 3,
449	        report_type: "model_operator_report".to_string(),
450	        model: MODEL.to_string(),
451	        phase: PHASE_DECODE.to_string(),
452	        config: ReportConfig {
453	            batch_size,
454	            kv_len,
455	            layers: NUM_LAYERS,
456	            tp_world_size: 1,
457	            iters,
458	            numeric_policy: policy_name(policy).to_string(),
459	        },
460	        schedule_source:
461	            "runtime trace: Qwen3Model::batch_decode eager DAG with CUDA Graph disabled".to_string(),
462	        total_measured_us: total,
463	        total_p99_us: total_p99,
464	        total_is_partial,
465	        pin_served: pin_served_count,
466	        per_token_served: per_token_served_count,
467	        schedule,
468	        by_op,
469	        by_call_site,
470	        coverage: coverage_rows.into_values().collect(),
471	    })
472	}
