474	fn measure_catalog(
475	    calls: &[KernelCall],
476	    iters: u64,
477	    policy: NumericPolicy,
478	) -> Result<HashMap<String, BenchEntry>> {
479	    let mut catalog = HashMap::new();
480	    for call in calls {
481	        if is_noop_all_reduce(call) {
482	            continue;
483	        }
484	        let key = bench_key(call)?;
485	        if catalog.contains_key(&key) {
486	            continue;
487	        }
488	        let measure = if let Some(reason) = classify(policy, &call.op) {
489	            Measure::Excluded(reason)
490	        } else {
491	            let stats = measure_call(call, iters).with_context(|| {
492	                format!("failed to measure {}\n{}", call.label, describe_call(call))
493	            })?;
494	            Measure::Faithful(stats)
495	        };
496	        catalog.insert(key.clone(), BenchEntry { key, measure });
497	    }
498	    Ok(catalog)
499	}
