703	fn measure_paged_decode_attention(call: &KernelCall, iters: u64) -> Result<LatencyStats> {
704	    let q = input(call, "q")?;
705	    let kv = input(call, "kv_buffer")?;
706	    let batch = axis(q, "batch")?;
707	    let q_dim = axis(q, "q_dim")?;
708	    let total_pages = axis(kv, "page")?;
709	    let num_layers = axis(kv, "layer")?;
710	    let kv_heads = axis(kv, "kv_head")?;
711	    let head_dim = axis(kv, "head_dim")?;
712	    let page_size = axis(kv, "pos_in_page")?;
713	    let kv_len = attr_usize(call, "kv_len")?;
714	    let pages_per_request = kv_len.div_ceil(page_size);
715	    let layout =
716	        KvLayout::new(num_layers, kv_heads, head_dim, page_size).expect("kv layout geometry");
717	    let ctx = DeviceContext::new()?;
718	    let q = HiddenStates::zeros(&ctx, q_dim, batch)?;
719	    let k = HiddenStates::zeros(&ctx, KV_DIM_VALUE, batch)?;
720	    let v = HiddenStates::zeros(&ctx, KV_DIM_VALUE, batch)?;
721	    let mut out = HiddenStates::zeros(&ctx, q_dim, batch)?;
722	    let kv_buffer: CudaSlice<bf16> = ctx.stream.alloc_zeros(total_pages * layout.page_stride)?;
723	    let (page_indices, page_indptr) = page_tables(batch, pages_per_request);
724	    let last_page_len_value = match kv_len % page_size {
725	        0 => page_size,
726	        rem => rem,
727	    };
728	    let last_page_len = vec![last_page_len_value as i32; batch];
729	    let positions = vec![kv_len.saturating_sub(1) as i32; batch];
730	    let request_indices: Vec<i32> = (0..batch as i32).collect();
731	    let page_indices_d = ctx.stream.clone_htod(&page_indices)?;
732	    let page_indptr_d = ctx.stream.clone_htod(&page_indptr)?;
733	    let last_page_len_d = ctx.stream.clone_htod(&last_page_len)?;
734	    let positions_d = ctx.stream.clone_htod(&positions)?;
735	    let request_indices_d = ctx.stream.clone_htod(&request_indices)?;
736	    let variant = attr_string(call, "variant")?;
737	
738	    // Replay the split-KV scalars from the recorded attrs; the Pin chunk is fixed off max_context,
739	    // not the step's kv_len.
740	    if variant == "split_kv" {
741	        let split_chunk_size = attr_usize(call, "split_chunk_size")?;
742	        let cap = attr_usize(call, "split_max_chunks")?;
743	        let padded_slots = batch * cap;
744	        let split_csr =
745	            ops::build_split_kv_csr(split_chunk_size, cap, &vec![kv_len; batch], batch)?;
746	        let split_kv_chunk_size = [split_chunk_size as i32];
747	        let split_request_indices_d = ctx.stream.clone_htod(&split_csr.request_indices)?;
748	        let split_kv_tile_indices_d = ctx.stream.clone_htod(&split_csr.kv_tile_indices)?;
749	        let split_kv_chunk_size_d = ctx.stream.clone_htod(&split_kv_chunk_size)?;
750	        let split_o_indptr_d = ctx.stream.clone_htod(&split_csr.o_indptr)?;
751	        let split_block_valid_mask_d = ctx.stream.clone_htod(&split_csr.block_valid_mask)?;
752	        let mut split_tmp_v = ctx.stream.alloc_zeros(padded_slots * q_dim)?;
753	        let mut split_tmp_s = ctx.stream.alloc_zeros(padded_slots * NUM_Q_HEADS)?;
754	        let stats = measure_loop(&ctx, iters, || {
755	            ops::paged_attention_batch_decode_split_kv_into(
756	                &ctx,
757	                &q,
758	                &k,
759	                &v,
760	                0,
761	                &kv_buffer,
762	                &layout,
763	                0,
764	                &page_indices_d,
765	                &page_indptr_d,
766	                &last_page_len_d,
767	                &positions_d,
768	                &request_indices_d,
769	                &split_request_indices_d,
770	                &split_kv_tile_indices_d,
771	                &split_kv_chunk_size_d,
772	                &split_o_indptr_d,
773	                &split_block_valid_mask_d,
774	                &mut split_tmp_v,
775	                &mut split_tmp_s,
776	                padded_slots,
777	                &mut out,
778	                NUM_Q_HEADS,
779	                batch,
780	            )
781	        })?;
782	        Ok(stats)
783	    } else if variant == "non_partition" {
784	        let kv_tile_indices = vec![0_i32; batch];
785	        let kv_chunk_size = vec![kv_len as i32; batch];
786	        let kv_tile_indices_d = ctx.stream.clone_htod(&kv_tile_indices)?;
787	        let kv_chunk_size_d = ctx.stream.clone_htod(&kv_chunk_size)?;
788	        let stats = measure_loop(&ctx, iters, || {
789	            ops::paged_attention_batch_decode_into(
790	                &ctx,
791	                &q,
792	                &k,
793	                &v,
794	                &kv_buffer,
795	                &layout,
796	                0,
797	                &page_indices_d,
798	                &page_indptr_d,
799	                &last_page_len_d,
800	                &positions_d,
801	                &request_indices_d,
802	                &kv_tile_indices_d,
803	                &kv_chunk_size_d,
804	                &mut out,
805	                NUM_Q_HEADS,
806	                batch,
807	            )
808	        })?;
809	        Ok(stats)
810	    } else {
811	        bail!("unsupported decode attention variant `{variant}`")
812	    }
813	}
