876	fn bench_key(call: &KernelCall) -> Result<String> {
877	    #[derive(Serialize)]
878	    struct Key<'a> {
879	        op: &'a str,
880	        inputs: &'a [pegainfer_kernels::tensor::TensorArg],
881	        outputs: &'a [pegainfer_kernels::tensor::TensorArg],
882	        attrs: BTreeMap<&'a str, &'a str>,
883	    }
