337	fn compose_report(
338	    batch_size: usize,
339	    kv_len: usize,
340	    iters: u64,
341	    schedule: Vec<KernelCall>,
342	    catalog: &HashMap<String, BenchEntry>,
343	    policy: NumericPolicy,
344	    pin_served_count: u64,
345	    per_token_served_count: u64,
346	) -> Result<ModelReport> {
347	    let mut op_rows: BTreeMap<String, Accum> = BTreeMap::new();
348	    let mut site_rows: BTreeMap<String, (String, Accum)> = BTreeMap::new();
349	    let mut coverage_rows: BTreeMap<(String, String), CoverageRow> = BTreeMap::new();
350	    let mut missing = Vec::new();
351	
352	    for call in &schedule {
353	        let site = normalize_call_site(&call.label);
354	        if is_noop_all_reduce(call) {
355	            // Counted toward call totals but contributes zero time on a single rank.
356	            let zero = LatencyStats::zero(iters);
357	            accumulate(op_rows.entry(call.op.clone()).or_default(), &zero);
358	            let (_, site_accum) = site_rows
359	                .entry(site.clone())
360	                .or_insert_with(|| (call.op.clone(), Accum::default()));
361	            accumulate(site_accum, &zero);
362	            coverage_rows
363	                .entry((site.clone(), call.op.clone()))
364	                .and_modify(|row| row.calls += 1)
365	                .or_insert(CoverageRow {
366	                    call_site: site,
367	                    op: call.op.clone(),
368	                    status: "no_op".to_string(),
369	                    calls: 1,
370	                    latency: Some(zero),
371	                    key: None,
372	                });
373	            continue;
374	        }
375	
376	        let key = bench_key(call)?;
377	        let Some(entry) = catalog.get(&key) else {
378	            missing.push(format!(
379	                "op={} label={} key={key}\n{}",
380	                call.op,
381	                call.label,
382	                describe_call(call)
383	            ));
384	            continue;
385	        };
386	
387	        if let Measure::Faithful(stats) = &entry.measure {
388	            accumulate(op_rows.entry(call.op.clone()).or_default(), stats);
389	            let (_, site_accum) = site_rows
390	                .entry(site.clone())
391	                .or_insert_with(|| (call.op.clone(), Accum::default()));
392	            accumulate(site_accum, stats);
393	        }
394	        coverage_rows
395	            .entry((site.clone(), call.op.clone()))
396	            .and_modify(|row| row.calls += 1)
397	            .or_insert(CoverageRow {
398	                call_site: site,
399	                op: call.op.clone(),
400	                status: match &entry.measure {
401	                    Measure::Faithful(_) => "measured",
402	                    Measure::Excluded(reason) => reason.status(),
403	                }
404	                .to_string(),
405	                calls: 1,
406	                latency: match &entry.measure {
407	                    Measure::Faithful(stats) => Some(stats.clone()),
408	                    Measure::Excluded(_) => None,
409	                },
410	                key: Some(entry.key.clone()),
411	            });
412	    }
413	
414	    if !missing.is_empty() {
415	        bail!("missing bench result:\n{}", missing.join("\n\n"));
416	    }
417	
418	    // Re-derived from the per-op accumulators (no-op all-reduce contributes 0),
419	    // so totals are summed in op order rather than schedule order, a sub-ULP
420	    // reshuffle that only touches this untracked target/ report.
421	    let total = op_rows.values().map(|accum| accum.total_us).sum::<f64>();
422	    let total_p99 = op_rows
423	        .values()
424	        .map(|accum| accum.total_p99_us)
425	        .sum::<f64>();
426	
427	    let mut by_op: Vec<_> = op_rows
428	        .into_iter()
429	        .map(|(op, accum)| rollup_row(op, accum, total))
430	        .collect();
431	    by_op.sort_by(|a, b| b.total_us.total_cmp(&a.total_us).then(a.op.cmp(&b.op)));
432	
433	    let mut by_call_site: Vec<_> = site_rows
434	        .into_iter()
435	        .map(|(call_site, (op, accum))| call_site_row(call_site, op, accum, total))
436	        .collect();
437	    by_call_site.sort_by(|a, b| {
438	        b.total_us
439	            .total_cmp(&a.total_us)
440	            .then(a.call_site.cmp(&b.call_site))
441	    });
442	
443	    let total_is_partial = catalog
444	        .values()
445	        .any(|entry| matches!(entry.measure, Measure::Excluded(_)));
446	
447	    Ok(ModelReport {
448	        schema: 3,
449	        report_type: "model_operator_report".to_string(),
450	        model: MODEL.to_string(),
451	        phase: PHASE_DECODE.to_string(),
452	        config: ReportConfig {
453	            batch_size,
454	            kv_len,
455	            layers: NUM_LAYERS,
456	            tp_world_size: 1,
457	            iters,
458	            numeric_policy: policy_name(policy).to_string(),
459	        },
460	        schedule_source:
461	            "runtime trace: Qwen3Model::batch_decode eager DAG with CUDA Graph disabled".to_string(),
462	        total_measured_us: total,
463	        total_p99_us: total_p99,
464	        total_is_partial,
465	        pin_served: pin_served_count,
466	        per_token_served: per_token_served_count,
467	        schedule,
468	        by_op,
469	        by_call_site,
470	        coverage: coverage_rows.into_values().collect(),
471	    })
472	}
