501	fn measure_call(call: &KernelCall, iters: u64) -> Result<LatencyStats> {
502	    if call.op == "paged_decode_attention" {
503	        return measure_paged_decode_attention(call, iters);
504	    }
505	    match call.op.as_str() {
506	        "embedding_batch" => measure_embedding(call, iters),
507	        "rms_norm_batch" => measure_rms_norm_batch(call, iters),
508	        "gemm_rows" => measure_gemm_rows(call, iters),
509	        "qk_norm_rope_batch_decode" => measure_qk_norm_rope(call, iters),
510	        "gemm" => measure_gemm(call, iters),
511	        "fused_add_rms_norm_batch" => measure_fused_add_rms_norm(call, iters),
512	        "silu_mul_fused_batch" => measure_silu_mul_fused(call, iters),
513	        "split_qkv" => measure_split_qkv(call, iters),
514	        "suppress_logits_bf16" => measure_suppress_logits(call, iters),
515	        other => bail!("no benchmark provider for op `{other}`"),
516	    }
517	}
518	
519	fn measure_embedding(call: &KernelCall, iters: u64) -> Result<LatencyStats> {
520	    let weight = input(call, "weight")?;
521	    let out = output(call, "out")?;
522	    let vocab = axis(weight, "vocab")?;
523	    let hidden = axis(weight, "hidden")?;
524	    let batch = axis(out, "batch")?;
525	    let ctx = DeviceContext::new()?;
526	    let embed = zero_matrix(&ctx, vocab, hidden)?;
527	    let token_ids: CudaSlice<u32> = ctx.stream.alloc_zeros(batch)?;
528	    let mut out = HiddenStates::zeros(&ctx, hidden, batch)?;
529	    measure_loop(&ctx, iters, || {
530	        ops::embedding_batch(&ctx, &embed, &token_ids, &mut out)?;
531	        Ok(())
532	    })
533	}
534	
535	fn measure_suppress_logits(call: &KernelCall, iters: u64) -> Result<LatencyStats> {
536	    let logits = output(call, "logits")?;
537	    let rows = axis(logits, "vocab")?;
538	    let batch = axis(logits, "batch")?;
539	    let ids = attr_usize(call, "ids")?;
540	    anyhow::ensure!(ids <= rows, "suppress_logits ids {ids} exceed rows {rows}");
541	    let tail = (rows - ids..rows)
542	        .map(u32::try_from)
543	        .collect::<std::result::Result<Vec<_>, _>>()?;
544	    let ctx = DeviceContext::new()?;
545	    let mut logits = HiddenStates::zeros(&ctx, rows, batch)?;
546	    let tail = ops::SuppressIds::upload(&ctx, &tail, rows)?;
547	    measure_loop(&ctx, iters, || {
548	        ops::suppress_logits_bf16_in_place(&ctx, &mut logits, &tail)?;
549	        Ok(())
550	    })
551	}
552	
