815	fn page_tables(batch: usize, pages_per_request: usize) -> (Vec<i32>, Vec<i32>) {
816	    let mut page_indices = Vec::with_capacity(batch * pages_per_request);
817	    let mut page_indptr = Vec::with_capacity(batch + 1);
818	    page_indptr.push(0);
819	    for request_idx in 0..batch {
820	        for page_offset in 0..pages_per_request {
821	            page_indices.push((request_idx * pages_per_request + page_offset) as i32);
822	        }
823	        page_indptr.push(page_indices.len() as i32);
824	    }
825	    (page_indices, page_indptr)
826	}
