828	fn measure_loop(
829	    ctx: &DeviceContext,
830	    iters: u64,
831	    mut launch: impl FnMut() -> Result<()>,
832	) -> Result<LatencyStats> {
833	    let mut cache_clear = L2CacheClear::new(ctx)?;
834	    let start = ctx
835	        .ctx
836	        .new_event(Some(sys::CUevent_flags::CU_EVENT_DEFAULT))?;
837	    let end = ctx
838	        .ctx
839	        .new_event(Some(sys::CUevent_flags::CU_EVENT_DEFAULT))?;
840	    launch()?;
841	    ctx.sync()?;
842	    let mut samples = Vec::with_capacity(iters as usize);
843	    for _ in 0..iters {
844	        cache_clear.clear(ctx)?;
845	        start.record(&ctx.stream)?;
846	        launch()?;
847	        end.record(&ctx.stream)?;
848	        samples.push(f64::from(start.elapsed_ms(&end)?) * 1.0e3);
849	    }
850	    LatencyStats::from_samples(iters, samples)
851	}
