1083	fn truncate(value: &str, max_chars: usize) -> String {
1084	    if value.chars().count() <= max_chars {
1085	        return value.to_string();
1086	    }
1087	    let mut truncated = value
1088	        .chars()
1089	        .take(max_chars.saturating_sub(3))
